module TopModule (
    input clk,
    input reset,
    input j,
    input k,
    output reg out
);

    // State encoding
    typedef enum reg [1:0] {
        OFF = 2'b00,
        ON  = 2'b01
    } state_t;

    state_t current_state, next_state;

    // State transition logic
    always @(*) begin
        case (current_state)
            OFF: begin
                if (j) begin
                    next_state = ON;
                end else begin
                    next_state = OFF;
                end
            end
            ON: begin
                if (k) begin
                    next_state = OFF;
                end else begin
                    next_state = ON;
                end
            end
            default: next_state = OFF; // Default state
        endcase
    end

    // State update and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= OFF;
            out <= 0;
        end else begin
            current_state <= next_state;
            out <= (current_state == ON);
        end
    end

endmodule
